import requests
import json

# Wayback Machine availability API
avail_url = 'https://archive.org/wayback/available'
params = {'url': 'https://www.sciencedirect.com/browse/journals-and-books?subject=life-sciences'}
headers = {'User-Agent': 'Mozilla/5.0'}
resp = requests.get(avail_url, params=params, headers=headers, timeout=15)
print('Availability Status:', resp.status_code)
if resp.status_code == 200:
    data = resp.json()
    print(json.dumps(data, indent=2))
    if 'archived_snapshots' in data:
        snapshot = data['archived_snapshots'].get('closest', {})
        if snapshot:
            print('Snapshot URL:', snapshot.get('url'))
            print('Timestamp:', snapshot.get('timestamp'))
else:
    print('Error:', resp.text[:200])
EOF
